export const orderViewScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}): string => `<script>
const ORDER_ID = ${a.id};
const API_REMOVE_ITEM = '${h(u('modules/orders/remove_item.php'))}';
const API_CANCEL = '${h(u('modules/orders/cancel.php'))}';

document.querySelectorAll('.btn-remove-item').forEach(function (btn) {
  btn.addEventListener('click', function () {
    if (!confirm('Remove this item from the order?')) return;
    udcPost(API_REMOVE_ITEM, { order_id: ORDER_ID, item_id: btn.dataset.id }).then(function (res) {
      if (res.success) { location.reload(); } else { alert((res.errors || ['Could not remove item.']).join(' ')); }
    });
  });
});
const btnCancel = document.getElementById('btnCancelOrder');
if (btnCancel) btnCancel.addEventListener('click', function () {
  new bootstrap.Modal(document.getElementById('cancelModal')).show();
});
const cancelConfirmBtn = document.getElementById('cancelConfirmBtn');
if (cancelConfirmBtn) cancelConfirmBtn.addEventListener('click', function () {
  const reason = document.getElementById('cancelReason').value.trim();
  if (!reason) { document.getElementById('cancelError').textContent = 'A reason is required.'; document.getElementById('cancelError').classList.remove('d-none'); return; }
  udcPost(API_CANCEL, { order_id: ORDER_ID, reason: reason }).then(function (res) {
    if (res.success) { location.reload(); } else {
      const box = document.getElementById('cancelError');
      box.textContent = (res.errors || ['Could not cancel order.']).join(' ');
      box.classList.remove('d-none');
    }
  });
});
</script>`;
export const orderPaymentScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}): string => `<script>
document.getElementById('addRow')?.addEventListener('click', function () {
  const wrap = document.getElementById('payRows');
  const row = document.querySelector('.pay-row').cloneNode(true);
  row.querySelectorAll('input').forEach(i => i.value = '');
  wrap.appendChild(row);
});
// Disable the submit button immediately on click to prevent an accidental double-click from
// firing two form submissions — the authoritative server-side lock+recheck in recordPayment()
// is the real safeguard, but this avoids the unnecessary second request in the first place.
document.getElementById('paymentForm')?.addEventListener('submit', function () {
  document.getElementById('submitBtn').disabled = true;
  document.getElementById('submitBtn').textContent = 'Processing...';
});
</script>`;
export const orderRefundScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}): string => `<script>
document.getElementById('creditToWallet')?.addEventListener('change', function () {
  document.getElementById('methodRows').classList.toggle('d-none', this.checked);
  document.getElementById('addMethodRow').classList.toggle('d-none', this.checked);
});
document.getElementById('addMethodRow')?.addEventListener('click', function () {
  const wrap = document.getElementById('methodRows');
  const row = document.querySelector('.method-row').cloneNode(true);
  row.querySelectorAll('input').forEach(i => i.value = '');
  wrap.appendChild(row);
});
</script>`;
